data.script:
function check(ok,message){if(!ok)throw Error(message);}
const before=editor.getText();
const sample='🐼  &amp;\r\n\t&lt;tag&gt;  \0end';
check(HTML.unescape(sample)==='🐼  &\r\n\t<tag>  \0end','literal bytes and entities');
check(HTML.unescape(HTML.escape('<One> & "Two" café 🐼'))==='<One> & "Two" café 🐼','escape/unescape roundtrip');
check(HTML.unescape('&lt;script&gt;alert(1)&lt;/script&gt;')==='<script>alert(1)</script>','literal decoded markup');
check(HTML.unescape('&amp;lt;')==='&lt;','one pass');
check(HTML.unescape('')===''&&HTML.escape('')==='','empty strings');
check(editor.getText()===before,'editor preserved');
console.log('HTML literal bytes and entities passed café 🐼');
